{
  "WorldCard_StaticEnvironment": {
    "Name": "欢愉仙都",
    "Classification": "都市异闻背景，雌性限定修仙设定",
    "CoreNature": "一个以现代都市为表象，内蕴独特“淫气”能量场的特殊世界。女性通过吸收雄性生物（尤其是“淫根”持有者）的精液进行修炼，科技发展与此“淫修”体系并行不悖。",
    "DefiningPhenomena": [
      {
        "Phenomenon": "淫气弥漫 (Yin Qi Permeation)",
        "Description": "环境中充斥着一种仅对女性修炼者有效的特殊能量“淫气”。其浓度、纯度及分布影响着修炼的效率和区域特性。"
      },
      {
        "Phenomenon": "精液驱动 (Semen-Driven Cultivation)",
        "Description": "女性修炼依赖于吸纳雄性生物的精液。雄性“淫根”的品质和稀有度，以及特定“淫兽”的精液，是修炼资源的核心。"
      },
      {
        "Phenomenon": "科技与修仙融合 (Tech-Cultivation Symbiosis)",
        "Description": "信息时代科技（如APP、生物工程）被广泛应用于辅助“淫修”，例如精液检测、淫根优化、资源交易等。"
      },
      {
        "Phenomenon": "社会结构分化 (Hierarchical Social Structure)",
        "Description": "社会地位与修炼境界及掌握的“精液资源”高度相关。女修居于主导，拥有优质“淫根”的男性则因其资源价值而具有特殊地位。"
      },
      {
        "Phenomenon": "文化特色鲜明 (Distinct Cultural Manifestations)",
        "Description": "文艺作品、消费品、教育体系乃至日常用语均深受“雌性至上”和“精液崇拜”的影响，形成了独特的社会风貌。"
      }
    ],
    "KeySettingPillars": [
      "历史转折点：淫气复苏、淫根显现、宗门崛起、精液产业化、兽精风潮。",
      "地理划分：基于淫气浓度与淫根资源分布的隐性区域，宗门与探险热点。",
      "统治与势力：世俗政府与“世界女子修仙联合会”（WFA）共管，各大宗门影响力巨大。",
      "阶级与特权：顶层女修大能掌控核心资源，向下逐级分配。",
      "性别动态：女性为修炼主体，男性（尤指淫根持有者）为修炼资源。",
      "信仰体系：主流信仰“淫祖女神”，并存对强大雄性神兽的图腾崇拜。",
      "经济模式：“淫石”为修仙界硬通货，围绕精液生产、交易、消费形成庞大产业链。"
    ],
    "World_Interaction_Note": "此设定卡描述的是一个客观存在的背景世界，其法则和现象构成角色行动与故事展开的舞台，本身不具备主观意识或直接与角色进行交互的能力。"
  }
}

