{
  "Lorebook_Entry": {
    "Title": "【淫根品级与供养者待遇 V1.4 - 自由凡品修订版】",
    "Version": "1.4",
    "LastUpdated": "淫气复苏历387年·秋分",
    "Author": "世界女子修仙联合会·资源评级办（特别修订）",
    "Introduction": "为进一步体现人道关怀并优化资源配置，特对“淫根”品级待遇标准进行修订。核心修订在于赋予“凡品淫根”持有者个人自由。所有“淫根”持有者，生殖器形态外观与常人无异，区别在于精液质、量及器官活性与尺寸。",
    "Tiers": [
      {
        "GradeName": "凡品淫根",
        "GradeSymbol": "凡",
        "EssenceProfile": {
          "Quality": "基础",
          "Description": "精液淫气稀薄，纯度尚可。满足练气期滋养或低阶丹药辅料。活性与尺寸略优于无根者。",
          "Yield": "标准月产，但受个人意愿与调养影响。"
        },
        "TreatmentPackage": {
          "Residence": "享有自由居住权，可自行选择居所。联合会提供过渡期住房补贴或推荐入住福利性“供养者互助公寓”。",
          "EssenceDonation": "精液捐献遵循自愿原则。每月完成指定次数的自愿捐献（可在官方指定采集点或合作机构进行），可获得相应福利包。",
          "Welfare": [
            "完成月度自愿捐献指标者，可领取“凡品培元丹”与低浓度“淫气亲和液”及少量生活津贴。",
            "所有登记在册的凡品淫根持有者均可享受基础公共医疗服务。",
            "联合会定期组织“淫根健康与保养”公益讲座及咨询。",
            "相比普通无根男性，仍享有因“资源潜力”带来的社会关注和部分优待机会（如特定职业的优先录用）。"
          ],
          "SocialPerception": "被视为拥有潜在价值的自由公民。其社会地位高于普通无根男性，但低于高品级供养者及女修。"
        }
      },
      {
        "GradeName": "良品淫根",
        "GradeSymbol": "良",
        "EssenceProfile": {
          "Quality": "中等",
          "Description": "精液淫气适中，助益筑基期，可炼中低阶丹药。活性与尺寸优于凡品，部分持久力佳。",
          "Yield": "月产较凡品高三至五成。"
        },
        "TreatmentPackage": {
          "Residence": "可申请入住“萃精阁”（进阶供养者公寓），提供独立套间或共享双人间。部分会被女修或精元工坊直接招募并提供住宿。",
          "EssenceDonation": "通常与女修或机构签订“精液供应协议”，按约履行。自由市场交易亦存在。",
          "Welfare": [
            "按协议或市场价获得报酬，包括“良品益精丸”、中浓度“淫气亲和液”及淫石。",
            "享受较全面医疗保障，含“淫根活力激发理疗”。",
            "可选择定制营养餐单，增益精液风味。",
            "有机会参与“精艺培训”及“优育计划”。"
          ],
          "SocialPerception": "有价值资源，部分资质优异者可能被低阶女修或家族选为长期“精伴”或重点培养对象。"
        }
      },
      {
        "GradeName": "优品淫根",
        "GradeSymbol": "优",
        "EssenceProfile": {
          "Quality": "上乘",
          "Description": "精液淫气浓郁精纯，裨益金丹期，炼高阶丹药佳品。尺寸可观，再生快，持久力惊人。",
          "Yield": "月产可达凡品两倍以上，单次爆发力强。"
        },
        "TreatmentPackage": {
          "Residence": "通常被各大宗门或权势女修接入私人府邸或专属“精料别院”，享受奢华供养。",
          "EssenceDonation": "按“主人”需求侍奉，拥有极高的自由和地位。",
          "Welfare": [
            "日享顶级药膳。",
            "专属医修团队日常保养与潜能激发。",
            "侍从照料，生活无忧，获淫石、法器等赏赐。",
            "被视为重要私产，主人会投入资源提升。"
          ],
          "SocialPerception": "珍贵修炼资源，身份与实力象征。"
        }
      },
      {
        "GradeName": "极品淫根",
        "GradeSymbol": "极",
        "EssenceProfile": {
          "Quality": "顶尖",
          "Description": "精液淫气近乎液化，纯净无匹，或带特殊属性，对元婴大修亦有奇效。淫根堪称“人间凶器”，尺寸活性远超常人，或具天赋神通。",
          "Yield": "重质不重量，单次精元能量巨大。"
        },
        "TreatmentPackage": {
          "Residence": "宗门核心秘境或顶级女修洞府，安保森严。",
          "EssenceDonation": "“开采”需仪式或在关键时刻进行，“初精”价值连城。其意愿会在特定条件下被高度重视。",
          "Welfare": [
            "享堪比宗门长老待遇，以“淫根安康”与“心情愉悦”为先。",
            "天材地宝、神丹妙药不限量供应。",
            "或签订“本命契约”，共享荣耀。",
            "个人意愿在不损根本前提下受高度尊重。"
          ],
          "SocialPerception": "“行走的天材地宝”，战略级资源，现世即引波澜。"
        }
      }
    ],
    "LegendaryMention": "只存在传说的尘元幻龙根。",
    "Addendum": "1. 严禁任何形式的强迫采精与虐待，特别是针对享有自由权的凡品淫根持有者。违者将受联合会严惩。\n2. 鼓励所有品级的“淫根”持有者积极参与“精液质量提升计划”与“和谐供养关系构建”项目。\n3. “精液市场”的交易需在联合会备案，确保公平与透明。"
  }
}

