{
  "Lorebook_Entry": {
    "Title": "【欢愉仙都经济体系：双轨通货 V1.1 - 精简版】",
    "Version": "1.1",
    "LastUpdated": "淫气复苏历388年·夏芒纪",
    "Author": "WFA经济规划部 & 诸国联合经济理事会（修订）",
    "Introduction": "欢愉仙都经济以“通用币”服务凡俗，以“淫石”驱动修仙，两者并行，构成独特经济格局。核心资源为“精液”。",

    "Section_1_Currencies_Overview": {
      "Universal_Coin": {
        "Name": "通用币 (UC$)",
        "Issuer": "全球经济联合理事会（世俗政府代表）。",
        "Form": "主数字货币，辅实体币。",
        "Use": "平民日常消费、世俗政府财政、非修仙商业、凡品淫根持有者部分福利。",
        "Characteristics": "高流动性、稳定、全球通用。"
      },
      "Yin_Stone": {
        "Name": "淫石 (淫石)",
        "Formation_Certification": "高浓度淫气凝结或高品质精液转化提炼；WFA认证品级（下、中、上、极品）并监控。",
        "Use": "女修间修仙资源交易（功法、法器、丹药）、高品质精液及淫根权益交易、宗门运作、高端精液制品结算、顶级拍卖。",
        "Characteristics": "价值高昂，与修炼实力挂钩，高阶流通，核心战略资源衡量标准。"
      }
    },

    "Section_2_Interaction_Value_System": {
      "Markets_Exchange": "通用币市场（民生）、淫石市场（修仙与核心资源）。官方设“特殊资源价值评估与兑换中心”，汇率浮动，严格管控。黑市存在高风险兑换。"
    },

    "Section_3_Main_Economic_Pillars_Flow": {
      "Semen_Economy": "“精液”为核心，形成从“源头”（淫根持有者/淫兽）到“最终消费”（女修/高端会所）的完整价值链，品质与稀有度决定价值。",
      "Tech_Companies": "参与通用币经济，同时是淫石经济重要组成（研发销售精液/淫气相关技术与高端产品）。",
      "Taxation": {
        "UC_Taxes": "个人/企业所得税（民用），消费税（普通商品）。",
        "YinShi_Taxes": "淫根持有税，精液交易增值税，高端精液制品特许经营与消费税。",
        "Distribution": "UC税维持世俗运转；淫石税由WFA主导，用于修仙界秩序、扶持低阶、研究应用，部分回馈世俗。"
      }
    },

    "Section_4_Regulation_Control_Dynamics": {
      "Oversight_Bodies": "WFA监管淫石流通、精液品质与交易、核心资源分配；世俗政府（全球经济理事会）调控通用币、维护凡俗市场。",
      "Inter_Faction_Competition": "各大宗门与国家在淫石储备、高端精液资源、新兴淫兽精液开发上激烈竞争，驱动经济与冲突。"
    },

    "Addendum": "本经济体系体现雌性限定修仙与科技并存特色，以“精液”为核心驱动。财富高度依赖对“精液”资源的掌控与利用效率。"
  }
}

